-- CreateTables：建表：注释、索引、外键一起建（外键排在全部建表之后）
IF OBJECT_ID(N'[t_note]', N'U') IS NULL CREATE TABLE [t_note] ([id] BIGINT IDENTITY(1,1) NOT NULL, [title] NVARCHAR(255) NULL, [author_id] BIGINT NOT NULL, [created_at] DATETIME2 NOT NULL, PRIMARY KEY ([id]));
IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty('MS_Description', 'SCHEMA', N'dbo', 'TABLE', N't_note', NULL, NULL)) EXEC sp_addextendedproperty 'MS_Description', N'笔记', 'SCHEMA', N'dbo', 'TABLE', N't_note';
IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty('MS_Description', 'SCHEMA', N'dbo', 'TABLE', N't_note', 'COLUMN', N'title')) EXEC sp_addextendedproperty 'MS_Description', N'标题', 'SCHEMA', N'dbo', 'TABLE', N't_note', 'COLUMN', N'title';
CREATE INDEX [t_note_author_id_created_at_idx] ON [t_note] ([author_id] ASC, [created_at] DESC);
ALTER TABLE [t_note] ADD CONSTRAINT [t_note_t_user_id_fk] FOREIGN KEY ([author_id]) REFERENCES [t_user] ([id]) ON DELETE CASCADE;
SELECT COUNT(*) FROM [t_note];

-- DbDefaults：库端默认值：建表时写上 DEFAULT；插入时为 null 的列不写，由库填上
IF OBJECT_ID(N'[t_draft]', N'U') IS NULL CREATE TABLE [t_draft] ([id] BIGINT IDENTITY(1,1) NOT NULL, [title] NVARCHAR(255) NULL, [status] NVARCHAR(255) DEFAULT 'draft' NULL, [priority] INTEGER DEFAULT 0 NULL, PRIMARY KEY ([id]));
INSERT INTO [t_draft] ([title]) VALUES (?);
-- params: ['周报']
SELECT TOP 1 [id],[title],[status],[priority] FROM [t_draft];

-- SyncTables：同步：先看要执行的语句，再执行；只增不删——改表名、改列名、加列、补索引
SELECT t.name AS table_name, CAST(p.value AS NVARCHAR(4000)) AS comment FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id LEFT JOIN sys.extended_properties p ON p.major_id = t.object_id AND p.minor_id = 0 AND p.class = 1 AND p.name = 'MS_Description' WHERE s.name = SCHEMA_NAME() ORDER BY t.name;
SELECT t.name AS table_name, c.name AS column_name, LOWER(ty.name) + CASE WHEN ty.name IN ('nvarchar', 'nchar') THEN '(' + CASE WHEN c.max_length = -1 THEN 'max' ELSE CAST(c.max_length / 2 AS VARCHAR(10)) END + ')' WHEN ty.name IN ('varchar', 'char', 'varbinary', 'binary') THEN '(' + CASE WHEN c.max_length = -1 THEN 'max' ELSE CAST(c.max_length AS VARCHAR(10)) END + ')' WHEN ty.name IN ('decimal', 'numeric') THEN '(' + CAST(c.precision AS VARCHAR(10)) + ',' + CAST(c.scale AS VARCHAR(10)) + ')' WHEN ty.name IN ('datetime2', 'time', 'datetimeoffset') THEN '(' + CAST(c.scale AS VARCHAR(10)) + ')' ELSE '' END AS column_type, c.is_nullable AS is_nullable, OBJECT_DEFINITION(c.default_object_id) AS column_default, (SELECT CAST(p.value AS NVARCHAR(4000)) FROM sys.extended_properties p WHERE p.major_id = t.object_id AND p.minor_id = c.column_id AND p.class = 1 AND p.name = 'MS_Description') AS comment, c.is_identity AS is_generated, CASE WHEN EXISTS (SELECT 1 FROM sys.index_columns ic JOIN sys.indexes i ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.is_primary_key = 1 AND ic.object_id = t.object_id AND ic.column_id = c.column_id) THEN 1 ELSE 0 END AS primary_key FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.columns c ON c.object_id = t.object_id JOIN sys.types ty ON ty.user_type_id = c.user_type_id WHERE s.name = SCHEMA_NAME() ORDER BY t.name, c.column_id;
SELECT t.name AS table_name, i.name AS index_name, i.is_unique AS is_unique, c.name AS column_name FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.indexes i ON i.object_id = t.object_id AND i.is_primary_key = 0 AND i.name IS NOT NULL JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = t.object_id AND c.column_id = ic.column_id WHERE s.name = SCHEMA_NAME() ORDER BY t.name, i.name, ic.key_ordinal;
SELECT t.name AS table_name, fk.name AS constraint_name, c.name AS column_name, rt.name AS referenced_table, rc.name AS referenced_column FROM sys.foreign_keys fk JOIN sys.tables t ON t.object_id = fk.parent_object_id JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id JOIN sys.columns c ON c.object_id = fkc.parent_object_id AND c.column_id = fkc.parent_column_id JOIN sys.tables rt ON rt.object_id = fkc.referenced_object_id JOIN sys.columns rc ON rc.object_id = fkc.referenced_object_id AND rc.column_id = fkc.referenced_column_id WHERE s.name = SCHEMA_NAME() ORDER BY t.name, fk.name, fkc.constraint_column_id;
EXEC sp_rename N'[t_tag]', N't_label';
EXEC sp_rename N'[t_label].[name]', N'title', 'COLUMN';
ALTER TABLE [t_label] ADD [color] NVARCHAR(255) NULL;
IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty('MS_Description', 'SCHEMA', N'dbo', 'TABLE', N't_label', 'COLUMN', N'color')) EXEC sp_addextendedproperty 'MS_Description', N'颜色', 'SCHEMA', N'dbo', 'TABLE', N't_label', 'COLUMN', N'color';
CREATE UNIQUE INDEX [t_label_title_uidx] ON [t_label] ([title] ASC);

-- ReadTables：读库结构：列、主键、索引、外键
SELECT t.name AS table_name, CAST(p.value AS NVARCHAR(4000)) AS comment FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id LEFT JOIN sys.extended_properties p ON p.major_id = t.object_id AND p.minor_id = 0 AND p.class = 1 AND p.name = 'MS_Description' WHERE s.name = SCHEMA_NAME() ORDER BY t.name;
SELECT t.name AS table_name, c.name AS column_name, LOWER(ty.name) + CASE WHEN ty.name IN ('nvarchar', 'nchar') THEN '(' + CASE WHEN c.max_length = -1 THEN 'max' ELSE CAST(c.max_length / 2 AS VARCHAR(10)) END + ')' WHEN ty.name IN ('varchar', 'char', 'varbinary', 'binary') THEN '(' + CASE WHEN c.max_length = -1 THEN 'max' ELSE CAST(c.max_length AS VARCHAR(10)) END + ')' WHEN ty.name IN ('decimal', 'numeric') THEN '(' + CAST(c.precision AS VARCHAR(10)) + ',' + CAST(c.scale AS VARCHAR(10)) + ')' WHEN ty.name IN ('datetime2', 'time', 'datetimeoffset') THEN '(' + CAST(c.scale AS VARCHAR(10)) + ')' ELSE '' END AS column_type, c.is_nullable AS is_nullable, OBJECT_DEFINITION(c.default_object_id) AS column_default, (SELECT CAST(p.value AS NVARCHAR(4000)) FROM sys.extended_properties p WHERE p.major_id = t.object_id AND p.minor_id = c.column_id AND p.class = 1 AND p.name = 'MS_Description') AS comment, c.is_identity AS is_generated, CASE WHEN EXISTS (SELECT 1 FROM sys.index_columns ic JOIN sys.indexes i ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.is_primary_key = 1 AND ic.object_id = t.object_id AND ic.column_id = c.column_id) THEN 1 ELSE 0 END AS primary_key FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.columns c ON c.object_id = t.object_id JOIN sys.types ty ON ty.user_type_id = c.user_type_id WHERE s.name = SCHEMA_NAME() ORDER BY t.name, c.column_id;
SELECT t.name AS table_name, i.name AS index_name, i.is_unique AS is_unique, c.name AS column_name FROM sys.tables t JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.indexes i ON i.object_id = t.object_id AND i.is_primary_key = 0 AND i.name IS NOT NULL JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = t.object_id AND c.column_id = ic.column_id WHERE s.name = SCHEMA_NAME() ORDER BY t.name, i.name, ic.key_ordinal;
SELECT t.name AS table_name, fk.name AS constraint_name, c.name AS column_name, rt.name AS referenced_table, rc.name AS referenced_column FROM sys.foreign_keys fk JOIN sys.tables t ON t.object_id = fk.parent_object_id JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id JOIN sys.columns c ON c.object_id = fkc.parent_object_id AND c.column_id = fkc.parent_column_id JOIN sys.tables rt ON rt.object_id = fkc.referenced_object_id JOIN sys.columns rc ON rc.object_id = fkc.referenced_object_id AND rc.column_id = fkc.referenced_column_id WHERE s.name = SCHEMA_NAME() ORDER BY t.name, fk.name, fkc.constraint_column_id;

